1	import {
2	  openSync,
3	  closeSync,
4	  writeSync,
5	  fsyncSync,
6	  mkdirSync,
7	  readFileSync,
8	  writeFileSync,
9	  truncateSync,
10	  renameSync,
11	  rmSync,
12	  existsSync,
13	  readdirSync,
