19	const LOG_NAME = 'bus.jsonl';
20	const LOG_TMP_NAME = 'bus.log.tmp';
21	const SNAPSHOT_NAME = 'bus.snapshot.json';
22	const SNAPSHOT_TMP_NAME = 'bus.snapshot.tmp';
23	// The log is a chain of segment files: the active `bus.jsonl` plus finalized
24	// `bus.<index>.jsonl` segments. Index order is oldest first; an index is
25	// never reused within the lifetime of a directory.
26	const SEGMENT_RE = /^bus\.(\d+)\.jsonl$/;
27	const segmentName = (index) => `bus.${String(index).padStart(10, '0')}.jsonl`;
