83	export function createBus({ path: dir, fsync = false, maxBytes } = {}) {
84	  if (typeof dir !== 'string' || dir.length === 0) {
85	    throw new TypeError('createBus: "path" must be a non-empty string');
86	  }
87	  // Omitted (undefined) means unlimited; any given value must be a positive
88	  // integer — zero, negatives, fractions and non-numbers are TypeErrors.
89	  let quota;
90	  if (maxBytes !== undefined) {
91	    if (typeof maxBytes !== 'number' || !Number.isInteger(maxBytes) || maxBytes <= 0) {
92	      throw new TypeError('createBus: "maxBytes" must be a positive integer');
93	    }
94	    quota = maxBytes;
95	  }
96	
97	  const logPath = path.join(dir, LOG_NAME);
98	  const logTmpPath = path.join(dir, LOG_TMP_NAME);
99	  const snapshotPath = path.join(dir, SNAPSHOT_NAME);
100	  const snapshotTmpPath = path.join(dir, SNAPSHOT_TMP_NAME);
101	
102	  let seq = 0; // seq of the last effective message
103	  let bytes = 0;
104	  let published = 0;
105	  let replayed = 0;
106	  // dedupKey -> { id, seq } for effective messages
107	  const dedup = new Map();
108	  // dedupKey -> { promise, resolve, reject } for first publish in flight
109	  const pending = new Map();
110	  // dedupKey -> { promise, resolve, reject } reserved by the first
111	  // in-flight batch carrying that key; lets later singles/batches share
112	  // the batch's first acknowledgement just like `pending` does for singles
113	  const groupPending = new Map();
114	  // consumer name -> position (seq of the last consumed message; 0 = none)
115	  const positions = new Map();
116	  // generation of the newest durable snapshot; 0 = no snapshot yet
117	  let snapshotGen = 0;
118	  // messages folded into the snapshot, served to replay/read after truncation
119	  let baseMessages = [];
120	  // Every message with seq <= horizon has been discarded by truncate().
121	  let horizon = 0;
122	  // Every message with seq <= foldedSeq lives in the snapshot, not the log.
123	  let foldedSeq = 0;
124	  // Index handed to the next finalized segment; never reused within a run.
125	  let nextSegmentIndex = 1;
126	  // Business bytes of the messages still retained (seq > horizon, i.e.
127	  // snapshot survivors plus live-log messages). Unlike the cumulative
128	  // `bytes` stat this shrinks when retention truncation frees messages;
129	  // compaction only reshapes the log and never changes it.
130	  let usageBytes = 0;
131	
132	  // ---- synchronous recovery so stats() is correct the moment createBus returns
133	  mkdirSync(dir, { recursive: true });
134	
135	  // A leftover tmp file is a snapshot that crashed mid-write. The pre-compact
136	  // log is still intact, so the half snapshot carries no state: drop it.
137	  rmSync(snapshotTmpPath, { force: true });
138	  // Likewise a log tmp left behind when compact crashed before the rename:
139	  // the live log (if any) is still the source of truth.
140	  rmSync(logTmpPath, { force: true });
