142	  if (existsSync(snapshotPath)) {
143	    const snap = JSON.parse(readFileSync(snapshotPath, 'utf8'));
144	    snapshotGen = snap.gen;
145	    seq = snap.seq;
146	    bytes = snap.bytes;
147	    published = snap.published;
148	    replayed = snap.replayed;
149	    // Snapshots written before truncation existed carry no horizon.
150	    horizon = snap.horizon ?? 0;
151	    foldedSeq = snap.seq;
152	    for (const [key, value] of snap.dedup) dedup.set(key, value);
153	    for (const [name, pos] of Object.entries(snap.positions)) positions.set(name, pos);
154	    baseMessages = snap.messages;
155	  }
156	
157	  const applyEntry = (entry) => {
158	    if (entry.t === 'm') {
159	      // At/below the horizon the message was discarded by truncation; only
160	      // its cumulative counters (carried by the marker) survive.
161	      if (entry.seq <= horizon) return;
162	      seq = entry.seq;
163	      bytes += entry.bytes;
164	      published += 1;
165	      if (typeof entry.d === 'string') {
166	        dedup.set(entry.d, { id: entry.id, seq: entry.seq });
167	      }
168	    } else if (entry.t === 's') {
169	      replayed += entry.n;
170	    } else if (entry.t === 'p') {
171	      positions.set(entry.name, entry.pos);
172	    }
173	  };
