175	  // A truncate marker is an absolute checkpoint: the cumulative counters,
176	  // positions and dedup table it carries replace whatever earlier segments
177	  // established, so recovery can start from the newest marker and ignore
178	  // everything before it.
179	  const applyMarker = (entry) => {
180	    seq = entry.seq;
181	    bytes = entry.bytes;
182	    published = entry.published;
183	    replayed = entry.replayed;
184	    horizon = entry.horizon;
185	    positions.clear();
186	    for (const [name, pos] of Object.entries(entry.positions)) positions.set(name, pos);
187	    dedup.clear();
188	    for (const [key, value] of entry.dedup) dedup.set(key, value);
189	  };
