191	  const markerLine = (gen) => JSON.stringify({ t: 'c', gen }) + '\n';
192	
193	  // Replay complete log lines and apply only the committed prefix.
194	  // A batch is bracketed by {t:'b',id} .. entries .. {t:'bk',id}: a begin
195	  // without its matching commit (crash mid-write, or overtaken by a newer
196	  // begin) is severed wholesale and none of its entries take effect.
197	  // Returns the byte offset just past the last committed line, so both a
198	  // torn trailing write and an uncommitted batch tail can be truncated.
199	  const recoverLog = (raw) => {
200	    let lineStart = 0;
201	    let committedEnd = 0;
202	    let group = null;
203	    for (let i = 0; i < raw.length; i++) {
204	      if (raw[i] !== 0x0a) continue;
205	      const entry = i > lineStart ? JSON.parse(raw.toString('utf8', lineStart, i)) : null;
206	      if (group !== null) {
207	        if (entry && entry.t === 'bk' && entry.id === group.id) {
208	          for (const e of group.entries) applyEntry(e);
209	          group = null;
210	          committedEnd = i + 1;
211	        } else if (entry && entry.t === 'b') {
212	          // The previous group never committed; start tracking the new one.
213	          group = { id: entry.id, entries: [] };
214	        } else if (entry) {
215	          group.entries.push(entry);
216	        }
217	      } else if (entry && entry.t === 'b') {
218	        group = { id: entry.id, entries: [] };
219	      } else {
220	        if (entry) {
221	          if (entry.t === 't') applyMarker(entry);
222	          else applyEntry(entry);
223	        }
224	        committedEnd = i + 1;
225	      }
226	      lineStart = i + 1;
227	    }
228	    return committedEnd;
229	  };
