231	  // Finalized segments present in the directory, oldest first.
232	  const listSegments = () => {
233	    const out = [];
234	    for (const name of readdirSync(dir)) {
235	      const match = SEGMENT_RE.exec(name);
236	      if (match) out.push({ index: Number(match[1]), path: path.join(dir, name) });
237	    }
238	    out.sort((a, b) => a.index - b.index);
239	    return out;
240	  };
