242	  // First complete line of a log file, or null when there is none.
243	  const firstEntry = (filePath) => {
244	    const raw = readFileSync(filePath);
245	    const nl = raw.indexOf(0x0a);
246	    if (nl <= 0) return null;
247	    try {
248	      return JSON.parse(raw.toString('utf8', 0, nl));
249	    } catch {
250	      return null;
251	    }
252	  };
253	
254	  // Highest message seq in a segment file; null when it carries no messages.
255	  const segmentMaxSeq = (filePath) => {
256	    const { entries } = parseLog(readFileSync(filePath));
257	    let max = null;
258	    for (const entry of entries) {
259	      if (entry.t === 'm' && (max === null || entry.seq > max)) max = entry.seq;
260	    }
261	    return max;
262	  };
263	
264	  const segments = listSegments();
265	  for (const seg of segments) {
266	    if (seg.index >= nextSegmentIndex) nextSegmentIndex = seg.index + 1;
267	  }
268	  // The ordered log is every finalized segment (oldest first) followed by
269	  // the active log file.
270	  const ordered = segments.map((seg) => seg.path);
271	  if (existsSync(logPath)) ordered.push(logPath);
272	
273	  // The newest anchor — a segment whose first line is a compact ('c') or
274	  // truncate ('t') marker for the current snapshot generation — starts the
275	  // live suffix of the log. Everything before it is folded into the snapshot
276	  // or checkpointed into that marker.
277	  let startAt = -1;
278	  for (let i = 0; i < ordered.length; i++) {
279	    const first = firstEntry(ordered[i]);
280	    if (first && (first.t === 'c' || first.t === 't') && first.gen === snapshotGen) {
281	      startAt = i;
282	    }
283	  }
284	
285	  if (snapshotGen > 0 && startAt < 0) {
286	    // Crash between the snapshot rename and the log reset: every byte still
287	    // on disk is already folded into the snapshot. Reset to a marker-led log
288	    // so the state is unambiguous from here on.
289	    for (const seg of segments) rmSync(seg.path, { force: true });
290	    writeFileSync(logPath, markerLine(snapshotGen));
291	  } else {
292	    // Replay the live suffix; a torn tail or uncommitted batch is severed.
293	    for (let i = Math.max(startAt, 0); i < ordered.length; i++) {
294	      const raw = readFileSync(ordered[i]);
295	      const committedEnd = recoverLog(raw);
296	      if (committedEnd < raw.length) truncateSync(ordered[i], committedEnd);
297	    }
298	    // Reconcile leftovers of an interrupted truncate/compact: finalized
299	    // segments before the anchor whose content is folded into the snapshot
