301	    // needs (above the horizon) stay untouched.
302	    for (let i = 0; i < startAt; i++) {
303	      const max = segmentMaxSeq(ordered[i]);
304	      if (max === null || max <= foldedSeq || max <= horizon) {
305	        rmSync(ordered[i], { force: true });
306	      }
307	    }
308	  }
309	
310	  // Recompute retained bytes from the surviving messages after recovery:
311	  // snapshot survivors plus messages in finalized segments and the active
312	  // log above both the horizon and the folded floor. Torn tails and
313	  // uncommitted batches were severed above, so their bytes never count —
314	  // usage always matches the messages actually alive.
315	  for (const m of baseMessages) {
316	    if (m.seq > horizon) usageBytes += Buffer.byteLength(JSON.stringify(m.record), 'utf8');
317	  }
318	  {
319	    const logFloor = Math.max(horizon, foldedSeq);
320	    const sumFile = (filePath) => {
321	      if (!existsSync(filePath)) return;
322	      const { entries } = parseLog(readFileSync(filePath));
323	      for (const entry of entries) {
324	        if (entry.t === 'm' && entry.seq > logFloor) usageBytes += entry.bytes;
325	      }
326	    };
327	    for (const seg of listSegments()) sumFile(seg.path);
328	    sumFile(logPath);
329	  }
330	
331	  // Reassigned by compact()/truncate() when they swap the active log.
332	  let fd = openSync(logPath, 'a');
333	
334	  let chain = Promise.resolve();
335	  let closed = false;
336	  // A failed append may leave a torn line; stop appending so later writes
337	  // cannot glue themselves onto it. The torn tail is truncated on reopen.
338	  let broken = false;
339	
340	  // All disk mutation by publish/replay/compact/truncate happens inside this
341	  // serial chain; writeSync keeps each append atomic with respect to the
342	  // event loop while still returning a Promise to callers.
343	  const enqueue = (job) => {
344	    const run = chain.then(job);
345	    // A failed job must not stall every later operation.
346	    chain = run.then(
347	      () => {},
348	      () => {},
349	    );
350	    return run;
351	  };
352	
353	  const writeLine = (entry) => {
354	    writeSync(fd, Buffer.from(JSON.stringify(entry) + '\n', 'utf8'));
355	    if (fsync) fsyncSync(fd);
356	  };
357	
358	  // Position writes are synchronous (register/advance/read are synchronous
359	  // methods) and order-independent against 'm'/'s' entries, so they append
360	  // directly rather than through the chain.
361	  const persistPosition = (name, pos) => {
362	    try {
363	      writeLine({ t: 'p', name, pos });
364	    } catch (err) {
365	      broken = true;
366	      throw err;
367	    }
368	  };
369	
370	  const assertOpen = () => {
371	    if (closed || broken) {
372	      throw new Error('bus is closed');
373	    }
374	  };
375	
376	  const assertName = (name) => {
377	    if (typeof name !== 'string' || name.length === 0) {
378	      throw new TypeError('consumer name must be a non-empty string');
379	    }
380	  };
381	
382	  // Messages with seq > pos that survived truncation, snapshot first then
383	  // live segments, ascending. A position below the truncation horizon simply
384	  // starts at the earliest surviving message: the gap is already truncated.
385	  const messagesAfter = (pos) => {
386	    const floor = Math.max(pos, horizon);
387	    const out = [];
388	    for (const m of baseMessages) {
389	      if (m.seq > floor) {
390	        // Snapshot messages are shared in-memory objects; hand out a copy so
391	        // callers cannot mutate replay/read results for later calls.
392	        out.push({ seq: m.seq, id: m.id, record: structuredClone(m.record) });
393	      }
394	    }
395	    // Log entries at/below foldedSeq are covered by the snapshot (a leftover
396	    // segment from an interrupted compaction can still be on disk).
397	    const logFloor = Math.max(floor, foldedSeq);
398	    const collect = (filePath) => {
399	      const { entries } = parseLog(readFileSync(filePath));
400	      for (const entry of entries) {
401	        if (entry.t === 'm' && entry.seq > logFloor) {
402	          out.push({ seq: entry.seq, id: entry.id, record: entry.record });
403	        }
404	      }
405	    };
406	    for (const seg of listSegments()) collect(seg.path);
407	    collect(logPath);
408	    return out;
409	  };
