411	  const bus = {
412	    publish(record) {
413	      if (closed) {
414	        return Promise.reject(new Error('bus is closed'));
415	      }
416	      if (record === null || typeof record !== 'object' || Array.isArray(record)) {
417	        return Promise.reject(new TypeError('publish: record must be a JSON object'));
418	      }
419	      const dedupKey = record.dedupKey;
420	      if (dedupKey !== undefined && typeof dedupKey !== 'string') {
421	        return Promise.reject(new TypeError('publish: dedupKey must be a string'));
422	      }
423	      try {
424	        assertJsonSafe(record);
425	      } catch (err) {
426	        return Promise.reject(err);
427	      }
428	      const size = Buffer.byteLength(JSON.stringify(record), 'utf8');
429	
430	      // Duplicate of an effective message (possibly recovered from disk).
431	      if (dedupKey !== undefined) {
432	        const first = dedup.get(dedupKey);
433	        if (first) {
434	          return Promise.resolve({ id: first.id, seq: first.seq });
435	        }
436	        const inflight = pending.get(dedupKey);
437	        if (inflight) {
438	          return inflight.promise;
439	        }
440	        const inflightGroup = groupPending.get(dedupKey);
441	        if (inflightGroup) {
442	          return inflightGroup.promise;
443	        }
444	      }
445	
446	      // Reserve in-flight dedup at call time so concurrent resends of the
447	      // same order share the first result; FIFO enqueue assigns seq in
448	      // invocation order.
449	      let resolveResult;
450	      let rejectResult;
451	      const promise = new Promise((resolve, reject) => {
452	        resolveResult = resolve;
453	        rejectResult = reject;
454	      });
455	      if (dedupKey !== undefined) {
456	        pending.set(dedupKey, { promise, resolve: resolveResult, reject: rejectResult });
457	      }
458	
459	      enqueue(() => {
460	        if (closed || broken) {
461	          throw new Error('bus is closed');
462	        }
463	        // Quota is checked inside the serial job, so a truncate queued
464	        // earlier releases its bytes before this publish is judged. An
465	        // exact fit succeeds; one byte over (or a single oversized record)
466	        // rejects before anything is written — state stays untouched.
467	        if (quota !== undefined && usageBytes + size > quota) {
468	          throw new RangeError('publish: retained bytes would exceed maxBytes');
469	        }
470	        const mySeq = seq + 1;
471	        const id = randomUUID();
472	        const entry = { t: 'm', seq: mySeq, id, bytes: size, record };
473	        if (dedupKey !== undefined) entry.d = dedupKey;
474	        try {
475	          // Durable before acknowledgement: state changes only after the
476	          // write (and optional fsync) succeeds.
477	          writeLine(entry);
478	        } catch (err) {
479	          broken = true;
480	          throw err;
481	        }
482	        seq = mySeq;
483	        bytes += size;
484	        usageBytes += size;
485	        published += 1;
486	        if (dedupKey !== undefined) {
487	          dedup.set(dedupKey, { id, seq: mySeq });
488	          pending.delete(dedupKey);
489	          resolveResult({ id, seq: mySeq });
490	        }
491	        return { id, seq: mySeq };
492	      }).then(
493	        (ack) => {
494	          if (dedupKey === undefined) resolveResult(ack);
495	        },
496	        (err) => {
497	          if (dedupKey !== undefined) pending.delete(dedupKey);
498	          rejectResult(err);
499	        },
500	      );
501	
502	      return promise;
503	    },
504	
505	    publishBatch(records) {
506	      // Spec: a non-array argument is always a synchronous TypeError.
507	      if (!Array.isArray(records)) {
508	        throw new TypeError('publishBatch: records must be an array');
509	      }
510	      if (closed) {
511	        return Promise.reject(new Error('bus is closed'));
512	      }
513	
514	      // Validate and serialize every record up front. Any single bad shape
515	      // (or value JSON cannot carry) rejects the whole group before the
516	      // serial chain is touched: seq/bytes/published/dedup/positions stay
517	      // exactly as they were.
518	      const prepared = [];
519	      try {
520	        for (const record of records) {
521	          if (record === null || typeof record !== 'object' || Array.isArray(record)) {
522	            throw new TypeError('publishBatch: record must be a JSON object');
523	          }
524	          const dedupKey = record.dedupKey;
525	          if (dedupKey !== undefined && typeof dedupKey !== 'string') {
526	            throw new TypeError('publishBatch: dedupKey must be a string');
527	          }
528	          assertJsonSafe(record);
529	          // Serialize exactly once per record: the byte count used for
530	          // stats and the bytes actually appended must be the same string.
531	          const recordJson = JSON.stringify(record);
532	          prepared.push({
533	            dedupKey,
534	            recordJson,
535	            size: Buffer.byteLength(recordJson, 'utf8'),
536	          });
537	        }
538	      } catch (err) {
539	        return Promise.reject(err);
540	      }
541	      if (prepared.length === 0) {
542	        return Promise.resolve([]);
543	      }
544	
545	      // Reserve the group's first-occurrence keys at call time, mirroring
546	      // publish()'s `pending`: a concurrent single or batch carrying the
547	      // same key shares this group's first acknowledgement. Keys already in
548	      // history or reserved by an earlier in-flight op are left alone.
549	      const reservations = new Map();
550	      for (const item of prepared) {
551	        const key = item.dedupKey;
552	        if (key === undefined) continue;
553	        if (dedup.has(key) || pending.has(key) || groupPending.has(key)) continue;
554	        if (reservations.has(key)) continue;
555	        let resolveResult;
556	        let rejectResult;
557	        const promise = new Promise((resolve, reject) => {
558	          resolveResult = resolve;
559	          rejectResult = reject;
560	        });
561	        // This promise is a coordination primitive: callers that race the
562	        // reservation attach their own branch (publish returns it). A group
563	        // with no such racer would otherwise leave the rejection unhandled
