565	        // handles the event for the process; racers still observe it.
566	        promise.catch(() => {});
567	        const reservation = { promise, resolve: resolveResult, reject: rejectResult };
568	        reservations.set(key, reservation);
569	        groupPending.set(key, reservation);
570	      }
