577	        // Resolve the whole plan against durable state inside the serial
578	        // job, so groups queued behind earlier publishes/batches observe
579	        // their committed dedup keys.
580	        const gid = randomUUID();
581	        let nextSeq = seq;
582	        let effectiveBytes = 0;
583	        const owned = new Map(); // key -> first acknowledgement within group
584	        const keyAcks = new Map(); // every dedup key's resolved acknowledgement
