586	          const key = item.dedupKey;
587	          if (key !== undefined) {
588	            const hist = dedup.get(key);
589	            if (hist) {
590	              const reuse = { id: hist.id, seq: hist.seq };
591	              keyAcks.set(key, reuse);
592	              return { reuse };
593	            }
594	            const earlier = owned.get(key);
595	            if (earlier) {
596	              return { reuse: earlier };
597	            }
598	          }
599	          nextSeq += 1;
600	          const id = randomUUID();
601	          const ack = { id, seq: nextSeq };
602	          if (key !== undefined) {
603	            owned.set(key, ack);
604	            keyAcks.set(key, ack);
605	          }
606	          // Splice the already-serialized record into the line so the
607	          // persisted bytes are exactly what `size` counted.
608	          let line = `{"t":"m","seq":${nextSeq},"id":${JSON.stringify(id)},"bytes":${item.size}`;
609	          if (key !== undefined) line += `,"d":${JSON.stringify(key)}`;
610	          line += `,"record":${item.recordJson}}\n`;
611	          effectiveBytes += item.size;
612	          return { effective: { ack, line, size: item.size, key } };
613	        });
614	
615	        // Shape validation happened at call time; quota is judged for the
616	        // whole group here, against committed state and counting only the
617	        // first occurrence of each key. One byte over rejects the entire
618	        // group before the bracket is opened — no seq, stat or file change.
619	        if (quota !== undefined && usageBytes + effectiveBytes > quota) {
620	          throw new RangeError('publishBatch: retained bytes would exceed maxBytes');
621	        }
622	
623	        // One begin-bracket, the group's new messages, one commit-bracket.
624	        // Recovery applies the bracketed entries only when the commit is
625	        // present, so a crash leaves no trace of the group.
626	        const buffers = [Buffer.from(JSON.stringify({ t: 'b', id: gid }) + '\n', 'utf8')];
627	        for (const part of planned) {
628	          if (part.effective) {
629	            buffers.push(Buffer.from(part.effective.line, 'utf8'));
630	          }
631	        }
632	        buffers.push(Buffer.from(JSON.stringify({ t: 'bk', id: gid }) + '\n', 'utf8'));
633	
634	        try {
635	          // Coalesce in small chunks (bounds peak memory for huge groups)
636	          // and loop over partial writes. Single-buffer writeSync is used
637	          // rather than writev so the append behaves identically on Windows.
638	          // Everything here is synchronous inside this job, so no position
639	          // write can interleave. The begin/commit brackets keep the group
640	          // atomic across a crash even if a partial write occurs.
641	          const CHUNK = 256;
642	          for (let i = 0; i < buffers.length; i += CHUNK) {
643	            const chunk = Buffer.concat(buffers.slice(i, i + CHUNK));
644	            let off = 0;
645	            while (off < chunk.length) {
646	              const written = writeSync(fd, chunk, off, chunk.length - off);
647	              if (!Number.isInteger(written) || written <= 0) {
648	                throw new Error('publishBatch: write made no progress, group is not durable');
649	              }
650	              off += written;
651	            }
652	          }
653	          if (fsync) fsyncSync(fd);
654	        } catch (err) {
655	          // Nothing is applied in memory; the uncommitted bracket is
656	          // severed on reopen. Stop the bus so later writes cannot glue
657	          // themselves onto the partial group. Reservations are reclaimed
658	          // by the outer catch below.
659	          broken = true;
660	          throw err;
661	        }
662	
663	        // Durable first, state after.
664	        for (const part of planned) {
665	          if (!part.effective) continue;
666	          const { ack, size, key } = part.effective;
667	          seq = ack.seq;
668	          bytes += size;
669	          usageBytes += size;
670	          published += 1;
671	          if (key !== undefined) dedup.set(key, { id: ack.id, seq: ack.seq });
672	        }
673	
674	        const acks = planned.map((part) =>
675	          part.reuse ? { id: part.reuse.id, seq: part.reuse.seq } : { id: part.effective.ack.id, seq: part.effective.ack.seq },
676	        );
677	        for (const [key, reservation] of reservations) {
678	          groupPending.delete(key);
679	          reservation.resolve(keyAcks.get(key));
680	        }
681	        return acks;
682	      }).catch((err) => {
683	        // Covers write failure inside the job and rejection before the job
684	        // body (closed/broken bus): release any reservation still pointing
685	        // at this failed group.
686	        for (const [key, reservation] of reservations) {
687	          if (groupPending.get(key) === reservation) groupPending.delete(key);
688	          reservation.reject(err);
689	        }
690	        throw err;
691	      });
692	    },
693	
694	    replay(from = 0) {
695	      if (closed) {
696	        return Promise.reject(new Error('bus is closed'));
697	      }
698	      if (typeof from !== 'number' || !Number.isInteger(from) || from < 0) {
699	        return Promise.reject(new RangeError('replay: from must be a non-negative integer'));
700	      }
701	
702	      return enqueue(() => {
703	        if (closed || broken) {
704	          throw new Error('bus is closed');
705	        }
706	        // replay(from) is inclusive of from; messagesAfter takes an
707	        // exclusive lower bound.
708	        const out = messagesAfter(from - 1);
709	        const n = out.length;
710	        if (n > 0) {
711	          try {
712	            writeLine({ t: 's', n });
713	          } catch (err) {
714	            broken = true;
715	            throw err;
716	          }
717	          replayed += n;
718	        }
719	        return out;
720	      });
721	    },
722	
723	    register(name) {
724	      assertOpen();
725	      assertName(name);
726	      const current = positions.get(name);
727	      // Re-registering an existing name must not reset its position.
728	      if (current !== undefined) {
729	        return current;
730	      }
731	      persistPosition(name, 0);
732	      positions.set(name, 0);
733	      return 0;
734	    },
735	
736	    advance(name, to) {
737	      assertOpen();
738	      assertName(name);
739	      if (typeof to !== 'number' || !Number.isInteger(to) || to < 0) {
740	        throw new RangeError('advance: position must be a non-negative integer');
741	      }
742	      const current = positions.get(name);
743	      if (current !== undefined) {
744	        if (to < current) {
745	          throw new RangeError('advance: position cannot move backwards');
746	        }
747	        if (to === current) {
748	          return current;
749	        }
750	      }
751	      // An unknown name is auto-registered, same as register() first.
752	      persistPosition(name, to);
753	      positions.set(name, to);
754	      return to;
755	    },
756	
757	    read(name) {
758	      assertOpen();
759	      assertName(name);
760	      let pos = positions.get(name);
761	      if (pos === undefined) {
762	        pos = 0;
763	        persistPosition(name, pos);
764	        positions.set(name, pos);
765	      }
