770	    compact() {
771	      if (closed) {
772	        return Promise.reject(new Error('bus is closed'));
773	      }
774	      return enqueue(() => {
775	        if (closed || broken) {
776	          throw new Error('bus is closed');
777	        }
778	        // Fold every surviving message: snapshot contents plus the live log,
779	        // skipping anything truncation already discarded.
780	        const messages = [];
781	        for (const m of baseMessages) {
782	          if (m.seq > horizon) messages.push(m);
783	        }
784	        const logFloor = Math.max(horizon, foldedSeq);
785	        const collect = (filePath) => {
786	          const { entries } = parseLog(readFileSync(filePath));
