809	        // truncated, so a crash anywhere leaves either the intact old log
810	        // (half tmp snapshot, discarded on reopen) or the new marker-led
811	        // log — never something in between.
812	        const tmpFd = openSync(snapshotTmpPath, 'w');
813	        try {
814	          writeSync(tmpFd, Buffer.from(JSON.stringify(snapshot) + '\n', 'utf8'));
815	          fsyncSync(tmpFd);
816	        } finally {
817	          closeSync(tmpFd);
818	        }
819	        renameSync(snapshotTmpPath, snapshotPath);
