821	        // segment unlinks) is best-effort: some platforms/filesystems expose
822	        // no directory fsync. A failure here weakens only the durability
823	        // guarantee, never the compaction result — the snapshot covers every
824	        // byte of the old log, so recovery folds it harmlessly on reopen.
825	        const syncDir = () => {
826	          try {
827	            const dirFd = openSync(dir, 'r');
828	            try {
829	              fsyncSync(dirFd);
830	            } finally {
831	              closeSync(dirFd);
832	            }
833	          } catch {
834	            // Directory sync unavailable/failed: compaction still stands.
835	          }
836	        };
837	        syncDir();
