847	        // A failed unlink leaves a harmless leftover: the foldedSeq floor
848	        // keeps it out of replay and recovery reconciles it on reopen.
849	        for (const seg of listSegments()) {
850	          try {
851	            rmSync(seg.path, { force: true });
852	          } catch {
853	            // Leftover segment: ignored now, cleaned up on reopen.
854	          }
855	        }
856	        let replaced = false;
857	        try {
858	          const newFd = openSync(logTmpPath, 'w');
859	          try {
860	            writeSync(newFd, Buffer.from(markerLine(gen), 'utf8'));
861	            fsyncSync(newFd);
862	          } finally {
863	            closeSync(newFd);
864	          }
865	          renameSync(logTmpPath, logPath);
866	          replaced = true;
867	          // Best-effort durability of the directory entry (may be
868	          // unavailable on Windows / some filesystems); a crash here
869	          // recovers to either the intact old log or the new one — both
870	          // fully covered by the snapshot above.
