877	            // snapshot regardless. Reopen it so close() still works, but
878	            // refuse further writes on this instance.
879	            try {
880	              fd = openSync(logPath, 'a');
881	            } catch {
882	              // Nothing usable: leave fd closed; every later op throws.
883	            }
884	          }
