886	          throw err;
887	        }
888	        snapshotGen = gen;
889	        foldedSeq = seq;
890	        baseMessages = messages;
891	      });
892	    },
893	
894	    truncate(before) {
895	      // Spec: a bound that is not a non-negative integer is always a
896	      // synchronous TypeError, even on a closed bus.
897	      if (typeof before !== 'number' || !Number.isInteger(before) || before < 0) {
