905	        return Promise.resolve();
906	      }
907	      return enqueue(() => {
908	        if (closed || broken) {
909	          throw new Error('bus is closed');
910	        }
911	        const oldHorizon = horizon;
912	
913	        // Truncation deals in whole segments only: seal the active segment
914	        // so its contents become eligible, and roll a fresh one. The rename
915	        // is atomic, so a crash here leaves the content under exactly one
