923	          } catch (err) {
924	            // Recover the append handle if possible; the bus refuses further
925	            // writes either way rather than risking a mixed-up log.
926	            try {
927	              fd = openSync(logPath, 'a');
928	            } catch {
929	              // Nothing usable: leave fd closed; every later op throws.
930	            }
