932	            throw err;
933	          }
934	        }
935	
936	        // Deletion is a prefix of the segment chain: sweep oldest first and
937	        // stop at the first segment that must stay. A segment stays while
938	        // any registered consumer's position has not passed its newest
939	        // message, or while that message is beyond the bound. A segment
940	        // without messages carries no retention weight and goes with the
941	        // prefix (its position/stat lines are checkpointed below).
942	        const doomed = [];
