963	            let held = false;
964	            for (const pos of positions.values()) {
965	              if (pos < max) {
966	                held = true;
967	                break;
968	              }
969	            }
970	            if (held) break;
971	            if (max > newHorizon) newHorizon = max;
972	            freedBytes += segmentBytes(seg.path);
973	          }
974	          doomed.push(seg);
975	        }
