977	        if (doomed.length === 0) {
978	          return;
979	        }
980	
981	        // Checkpoint every state the doomed segments carry BEFORE unlinking
982	        // them. The marker is the first line of the fresh active segment and
983	        // becomes the new recovery anchor, so a crash after it lands loses
984	        // nothing: recovery resets to the marker and reconciles leftovers.
985	        const marker = {
986	          t: 't',
987	          gen: snapshotGen,
988	          horizon: newHorizon,
989	          seq,
990	          bytes,
991	          published,
992	          replayed,
993	          positions: Object.fromEntries(positions),
994	          dedup: Array.from(dedup.entries()),
995	        };
