997	          writeSync(fd, Buffer.from(JSON.stringify(marker) + '\n', 'utf8'));
998	          // Always fsync here regardless of the fsync option: deletion is
999	          // only safe once the checkpoint is durable.
1000	          fsyncSync(fd);
1001	        } catch (err) {
1002	          broken = true;
1003	          throw err;
1004	        }
1005	        // Make the roll's and the marker's directory entries durable before
1006	        // unlinking. Where directory sync is unavailable, keep the segments:
1007	        // the marker is valid either way, and a later truncate or the next
1008	        // recovery finishes the job.
1009	        let dirSynced = false;
1010	        try {
1011	          const dirFd = openSync(dir, 'r');
1012	          try {
1013	            fsyncSync(dirFd);
1014	            dirSynced = true;
1015	          } finally {
1016	            closeSync(dirFd);
1017	          }
1018	        } catch {
1019	          // Deletion is skipped; everything else about the truncate stands.
1020	        }
1021	        if (dirSynced) {
1022	          for (const seg of doomed) {
1023	            try {
1024	              rmSync(seg.path, { force: true });
1025	            } catch {
