1044	        // (marker durable, unlinks attempted); release their quota. The
1045	        // horizon can also run past messages folded into the snapshot:
1046	        // release their bytes too, so usage matches the surviving set.
1047	        // The cumulative stats bytes/published deliberately stay put.
1048	        usageBytes -= freedBytes;
