1050	          if (m.seq > oldHorizon && m.seq <= newHorizon) {
1051	            usageBytes -= Buffer.byteLength(JSON.stringify(m.record), 'utf8');
1052	          }
1053	        }
1054	      });
1055	    },
1056	
1057	    stats() {
1058	      return { seq, bytes, published, replayed };
1059	    },
1060	
1061	    // Business bytes of the messages still retained (not yet discarded by
1062	    // retention truncation). Compaction does not change it; an empty bus is
1063	    // zero. Readable after close, like stats().
1064	    usage() {
1065	      return usageBytes;
1066	    },
1067	
1068	    close() {
1069	      if (closed) {
1070	        return Promise.resolve();
1071	      }
1072	      closed = true;
1073	      // Reject any publish whose dedup reservation is still queued.
1074	      for (const [key, p] of pending) {
1075	        p.reject(new Error('bus is closed'));
1076	        pending.delete(key);
1077	      }
1078	      // And every reservation held by a batch still waiting in the chain.
1079	      for (const [key, g] of groupPending) {
1080	        g.reject(new Error('bus is closed'));
1081	        groupPending.delete(key);
1082	      }
