1084	        // A failed compact may have left the append handle unusable; close
1085	        // must stay idempotent and never reject.
1086	        try {
1087	          if (fsync) fsyncSync(fd);
1088	        } catch {
1089	          // Ignore: the handle may already be closed.
1090	        }
1091	        try {
1092	          closeSync(fd);
1093	        } catch {
1094	          // Already closed by the compact failure path.
1095	        }
1096	      });
1097	    },
1098	  };
1099	
1100	  return bus;
1101	}
